const sportSheets = {
  Football: football,
  Cricket: cricket,
  Tennis: tennis,
  Golf: golf,
  Rugby: rugby,
  'Olympic Venues': olympics,
  Boxing: boxing,
};

// Read the existing workbook to preserve the Formula 1 sheet untouched.
const dbPath = path.join(process.cwd(), 'public/databases/iconic-venues.xlsx');
const existingWb = XLSX.readFile(dbPath);
const f1Sheet = existingWb.Sheets['Formula 1'];

const wb = XLSX.utils.book_new();
XLSX.utils.book_append_sheet(wb, f1Sheet, 'Formula 1');

let totalVenues = XLSX.utils.sheet_to_json(f1Sheet).length;
console.log(`✅ Formula 1: ${totalVenues} venues (unchanged)`);

for (const [sheetName, venues] of Object.entries(sportSheets)) {
  const ws = XLSX.utils.json_to_sheet(venues);
  XLSX.utils.book_append_sheet(wb, ws, sheetName);
  totalVenues += venues.length;
  console.log(`✅ ${sheetName}: ${venues.length} venues (sport-specific schema)`);
}

XLSX.writeFile(wb, dbPath);
console.log(`\nTotal venues: ${totalVenues}`);
console.log(`Database written to: ${dbPath}`);
